package es.riegocerca.maps;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import org.json.*;
public class MainActivity extends Activity{WebView w;GeolocationPermissions.Callback geo;String origin;static final int LOC=7,IMPORT=9;public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.addJavascriptInterface(new MapsBridge(this),"AndroidMaps");w.addJavascriptInterface(new ImportBridge(this,IMPORT),"AndroidImport");w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){try{if(u.startsWith("https://wa.me/")||u.startsWith("https://earth.google.com/")){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(u));if(u.contains("earth.google.com"))i.setPackage("com.google.earth");try{startActivity(i);}catch(Exception e){i.setPackage(null);startActivity(i);}return true;}}catch(Exception e){}return false;}});w.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){origin=o;geo=c;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED){c.invoke(o,true,true);geo=null;}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);}});w.loadUrl("file:///android_asset/index.html");}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==IMPORT&&c==RESULT_OK&&d!=null&&d.getData()!=null){try{JSONArray a=new NativeTabularImporter(this).read(d.getData());String js="window.receiveImportedRows("+JSONObject.quote(a.toString())+")";w.post(()->w.evaluateJavascript(js,null));}catch(Exception e){String msg=e.getMessage()==null?e.toString():e.getMessage();w.post(()->w.evaluateJavascript("document.querySelector('#status').textContent="+JSONObject.quote("Error al importar: "+msg),null));}}}public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC&&geo!=null){boolean ok=false;for(int x:g)ok|=x==PackageManager.PERMISSION_GRANTED;geo.invoke(origin,ok,true);geo=null;}}}
